// ---- PASS B station steps (generated by scripts/nom_pb1b_cut.py) ----

StationStep networkGlonassAnchorRows(StationBuild& build) {
    // ---- From the station build (generated by scripts/nom_pb1b_cut.py,
    //      each line checked by scripts/nom_pb1b_verify.py). ----
    const GnssConfig& config_ = build.config;
    NetStation& st = build.st;
    StationAssembly& R = build.R;
    std::map<int, int>& h2local = R.h2local;
    // ---- End of the bindings ----

    // GLONASS local-nuisance anchors (code-only network scope).
    // The per-epoch absolute network solve carries no Kalman prior on the
    // local nuisances, and GLONASS, unlike GPS/Galileo, has a per-FCN-slot
    // receiver IFB on every band, so there is no IFB-free reference-band code
    // to anchor the slant iono.  Two unobservable families make the local
    // block N_rr non-positive-definite (the kernel then drops the whole
    // station, including its valid GPS/Galileo rows):
    //   (1) each GLONASS satellite's slant iono I_s, fully confounded with
    //       that satellite's IFB(band,k) + ambiguity (the code rows determine
    //       only the sum IFB + alpha*I, leaving I_s free);
    //   (2) the {IFB(k)} <-> GLONASS-ISB common mode, unanchored unless a
    //       central-channel k=0 satellite is up (GLONASS has only ~2-3).
    // One loose zero-mean prior row is appended per GLONASS per-slot IFB
    // column and per GLONASS per-satellite iono column to regularize exactly
    // those directions.  This is product-safe: the emitted satellite clock
    // depends only on the data-determined IFB+alpha*I sum (and the
    // cross-station consensus), never on how this unobservable split is
    // resolved, so anchoring the split toward zero does not perturb the
    // shared clock.  Weight 1.0 (sigma 1 m) sits well above the kernel's
    // relative PD floor (1e-12 * d_max, d_max ~ the 1e10 pivot ambiguity
    // pins), so even the pivot block stays PD.  Built into the station's own
    // block (no shared write); inert for stations without GLONASS and when
    // the flag is off.
    if (!(config_.enableGlonassNetwork())) return StationStep::Next;
    std::vector<int> anchor_cols;
    std::vector<RowTag> anchor_tag;   // one contribution tag per anchor row
    for (const auto& [key, sidx] : st.sm->getCodeBiasStates()) {
        if (!StateKeys::isGlonassPerSlotIfbKey(key)) continue;
        const auto hit = h2local.find(static_cast<int>(sidx));
        if (hit != h2local.end()) {
            anchor_cols.push_back(hit->second);
            anchor_tag.push_back(RowTag{ContributionKind::GloIfbAnchor, {}, {}});
        }
    }
    for (const auto& [sat, sidx] : st.sm->getIonosphereStates()) {
        if (systemOfSat(sat) != System::GLONASS) continue;  // GLONASS iono only
        const auto hit = h2local.find(static_cast<int>(sidx));
        if (hit != h2local.end()) {
            anchor_cols.push_back(hit->second);
            anchor_tag.push_back(makeRowTag(ContributionKind::GloIonoAnchor, sat));
        }
    }
    const int ni = static_cast<int>(anchor_cols.size());
    if (ni > 0) {
        constexpr double kGloAnchorWeight = 1.0;  // 1/(1 m)^2
        const Eigen::Index m0 = R.A_s.rows();
        R.A_s.conservativeResize(m0 + ni, Eigen::NoChange);
        R.A_s.bottomRows(ni).setZero();
        R.A_r.conservativeResize(m0 + ni, Eigen::NoChange);
        R.A_r.bottomRows(ni).setZero();
        R.w.conservativeResize(m0 + ni);
        R.y.conservativeResize(m0 + ni);
        for (int k = 0; k < ni; ++k) {
            R.A_r(m0 + k, anchor_cols[k]) = 1.0;
            R.w(m0 + k) = kGloAnchorWeight;
            R.y(m0 + k) = 0.0;  // toward 0 (absolute solve, lin pt 0)
        }
        R.row_tags.insert(R.row_tags.end(), anchor_tag.begin(), anchor_tag.end());
    }
    return StationStep::Next;
}

StationStep networkSimZeroIonoRows(StationBuild& build) {
    // ---- From the station build (generated by scripts/nom_pb1b_cut.py,
    //      each line checked by scripts/nom_pb1b_verify.py). ----
    const GnssConfig& config_ = build.config;
    NetStation& st = build.st;
    StationAssembly& R = build.R;
    std::map<int, int>& h2local = R.h2local;
    // ---- End of the bindings ----

    // Test-only zero-ionosphere rows (network.sim_zero_iono_sigma_m).
    // A fixture simulated without ionosphere is matched on the estimator side by
    // one row per slant-ionosphere column of this station, +1 on the column, aimed
    // at absolute zero: the column is an increment on the state's linearization
    // value, so the row's target is minus that value.  Off (0) adds nothing.
    if (!(config_.getNetworkConfig().sim_zero_iono_sigma_m > 0.0)) return StationStep::Next;
    const double zi_sig = config_.getNetworkConfig().sim_zero_iono_sigma_m;
    const Eigen::VectorXd zi_xlin = st.sm->getStateVector();
    std::vector<int> zi_cols;
    std::vector<double> zi_y;
    std::vector<RowTag> zi_tag;
    for (const auto& [sat, sidx] : st.sm->getIonosphereStates()) {
        const auto hit = h2local.find(static_cast<int>(sidx));
        if (hit == h2local.end()) continue;
        const int si = static_cast<int>(sidx);
        if (si < 0 || si >= zi_xlin.size() || !std::isfinite(zi_xlin(si))) continue;
        zi_cols.push_back(hit->second);
        zi_y.push_back(-zi_xlin(si));
        zi_tag.push_back(makeRowTag(ContributionKind::SimZeroIono, sat));
    }
    const int nz = static_cast<int>(zi_cols.size());
    if (nz > 0) {
        const Eigen::Index m0 = R.A_s.rows();
        R.A_s.conservativeResize(m0 + nz, Eigen::NoChange);
        R.A_s.bottomRows(nz).setZero();
        R.A_r.conservativeResize(m0 + nz, Eigen::NoChange);
        R.A_r.bottomRows(nz).setZero();
        R.w.conservativeResize(m0 + nz);
        R.y.conservativeResize(m0 + nz);
        for (int k = 0; k < nz; ++k) {
            R.A_r(m0 + k, zi_cols[k]) = 1.0;
            R.w(m0 + k) = 1.0 / (zi_sig * zi_sig);
            R.y(m0 + k) = zi_y[k];
        }
        R.row_tags.insert(R.row_tags.end(), zi_tag.begin(), zi_tag.end());
    }
    return StationStep::Next;
}

